import {readFile,writeFile} from 'node:fs/promises';
import {connectOperator} from '../tools/staging/m77-common';
import {hostedDumpEnvironment} from '../tools/staging/m78-hosted-database';
import {inventory} from '../tools/staging/m78-inventory';
const sha=(v:string)=>new Bun.CryptoHasher('sha256').update(v).digest('hex');
function check(v:unknown):asserts v{if(!v)throw Error('Diagnostic refused');}
const observedText=await readFile('.superpowers/m78-interrupted-sessions-observed.json','utf8');
check(sha(observedText)==='4570ae628e05c71d8feab14acc6e5c04fe985f842ab2cdf8d111b19031d1f273');
const selected=JSON.parse(observedText).observations.map((o:any)=>o.sessions[0]);check(selected.length===4);
const input=JSON.parse(await Bun.stdin.text());check(input.operatorId==='/root'&&Object.keys(input).sort().join(',')==='operatorDatabaseUrl,operatorId');
hostedDumpEnvironment(input.operatorDatabaseUrl);
let stage='connect';const data:Record<string,unknown>={};
const db=await connectOperator(input.operatorDatabaseUrl);
try{
 try{await db.transaction(async tx=>{
  await tx.exec('set transaction isolation level repeatable read read only');
  stage='identity';data.identity=(await tx.query<any>("select current_database() database,current_user actor,current_setting('transaction_read_only') read_only")).rows[0];
  check((data.identity as any).database==='postgres'&&(data.identity as any).actor==='postgres'&&(data.identity as any).read_only==='on');
  stage='privileges';data.privileges=(await tx.query<any>("select has_table_privilege(current_user,'auth.sessions','SELECT') as session_select,has_table_privilege(current_user,'auth.sessions','DELETE') as session_delete,has_table_privilege(current_user,'auth.refresh_tokens','SELECT') as refresh_select,has_table_privilege(current_user,'auth.mfa_amr_claims','SELECT') as mfa_select")).rows[0];
  stage='foreign_keys';data.foreignKeys=(await tx.query<any>("select conname,conrelid::regclass::text as child_table,confrelid::regclass::text as parent_table,pg_get_constraintdef(oid) as definition from pg_constraint where contype='f' and confrelid='auth.sessions'::regclass order by conname")).rows;
  stage='triggers';data.triggers=(await tx.query<any>("select tgname,tgrelid::regclass::text as table_name,tgenabled from pg_trigger where not tgisinternal and tgrelid in ('auth.sessions'::regclass,'auth.refresh_tokens'::regclass,'auth.mfa_amr_claims'::regclass) order by table_name,tgname")).rows;
  stage='selected_metadata';const metadata=[];
  for(const s of selected){
   const rows=(await tx.query<any>('select id,user_id,created_at::text as created_at_exact,updated_at::text as updated_at_exact,created_at=$3::timestamptz as original_created_exact,updated_at=$4::timestamptz as original_updated_exact from auth.sessions where id=$1 and user_id=$2',[s.id,s.user_id,s.created_at,s.updated_at])).rows;
   metadata.push({selected:s,rows});
  }
  data.selectedMetadata=metadata;
  stage='session_counts';data.sessionCount=(await tx.query<any>('select count(*)::text as count from auth.sessions')).rows[0];
  stage='refresh_counts';data.refreshCounts=(await tx.query<any>('select session_id,count(*)::text as count from auth.refresh_tokens group by session_id order by session_id nulls first limit 10001')).rows;
  stage='mfa_counts';data.mfaCounts=(await tx.query<any>('select session_id,count(*)::text as count from auth.mfa_amr_claims group by session_id order by session_id nulls first limit 10001')).rows;
  stage='application_inventory';const app=await inventory(tx);data.applicationInventorySha256=sha(JSON.stringify(app));data.applicationTableCount=app.tables.length;
  stage='complete';
 });data.status='read_only_diagnostic_completed';}
 catch(error){data.status='read_only_diagnostic_failed';const code=(error as any)?.code;data.sqlstate=typeof code==='string'&&/^[0-9A-Z]{5}$/.test(code)?code:null;}
 await writeFile('.superpowers/m78-session-cleanup-diagnostic-result.json',JSON.stringify({observedAt:new Date().toISOString(),stage,...data,applicationWrites:0,authenticationWrites:0,observationSha256:sha(observedText)},null,2)+'\n',{flag:'wx'});
 console.log(JSON.stringify({status:data.status,stage,sqlstate:data.sqlstate??null,applicationWrites:0,authenticationWrites:0}));
}finally{await db.close();}

param(
  [Parameter(Mandatory=$true)][ValidateSet('observe')][string]$Mode,
  [Parameter(Mandatory=$true)][string[]]$OperationArguments
)
$ErrorActionPreference='Stop'
try {
  $workspace=[IO.Path]::GetFullPath('C:/Users/nimab/.codex/worktrees/4441/Neuvetra')
  $scriptFull=Join-Path $workspace '.superpowers/m78-session-cleanup-diagnose.ts'
  if($Mode -ne 'observe' -or $OperationArguments.Count -ne 1 -or $OperationArguments[0] -ne 'read-only'){throw 'argument count'}
  if((Get-FileHash -LiteralPath $scriptFull).Hash.ToLowerInvariant() -cne '3d5516cf574b93a3989b3e78f41f77ab0ad21f969443237f4bd81578182152b4'){throw 'diagnostic changed'}
  $values=@()
  foreach($line in [IO.File]::ReadAllLines('C:/Users/nimab/Neuvetra/env.json.txt')){
    if($line -match '^\s*(?:export\s+)?DATABASE_URL\s*=\s*(.*?)\s*$'){
      $value=$Matches[1]
      if($value.StartsWith('"')){$value=ConvertFrom-Json $value}elseif($value.StartsWith("'") -and $value.EndsWith("'")){$value=$value.Substring(1,$value.Length-2)}
      $values+=$value
    }elseif($line -match '^\s*"DATABASE_URL"\s*:\s*("(?:[^"\\]|\\.)*")\s*,?\s*$'){$values+=(ConvertFrom-Json $Matches[1])}
  }
  if($values.Count -ne 1){throw 'connection selection'}
  $payload=@{operatorDatabaseUrl=[string]$values[0];operatorId='/root'} | ConvertTo-Json -Compress
  $start=[Diagnostics.ProcessStartInfo]::new()
  $start.FileName='C:/Users/nimab/.bun/bin/bun.exe'
  $start.WorkingDirectory=$workspace
  $start.ArgumentList.Add('run');$start.ArgumentList.Add($scriptFull);$start.ArgumentList.Add($Mode)
  foreach($argument in $OperationArguments){$start.ArgumentList.Add($argument)}
  $start.UseShellExecute=$false;$start.CreateNoWindow=$true
  $start.RedirectStandardInput=$true;$start.RedirectStandardOutput=$true;$start.RedirectStandardError=$true
  $process=[Diagnostics.Process]::Start($start)
  $process.StandardInput.Write($payload);$process.StandardInput.Close()
  $output=$process.StandardOutput.ReadToEndAsync();$errors=$process.StandardError.ReadToEndAsync()
  $process.WaitForExit()
  Write-Output $output.Result
  if($process.ExitCode -ne 0){Write-Output 'M78 private database operation failed; sensitive diagnostics withheld.';exit 1}
}catch{Write-Output 'M78 private database operation unavailable; sensitive diagnostics withheld.';exit 1}
